import React, {useState} from 'react';
import Header from './Header';
import './UserPage.css';
import Footer from './Footer';
import user from './User.jpg'

//username, password, email, phone, address, past orders
const Userpage=()=>{
    const [quantity, setQuantity] = useState(1);
    const [message, setMessage] = useState('');
    const [mainImage, setMainImage] = useState(saree1);
    const [items, setItems] = useState([
        { id: 1, name: 'saree name', price: 5000000, quantity: 1, imageUrl: 'saree1.jpg' },
      ]);

    const saree = {
        name: "Traditional Silk Saree",
        price: "₹4,500",
        description: "A beautiful traditional silk saree, perfect for weddings and festive occasions.",
        fabric: "cotton", 
        origin: "Bengal", 
        craft: "Hand Painted", 
        occasion: "Casual Wear",
    };

    const incrementQuantity = (id) => {
        setItems(items.map(item => 
            item.id === id ? { ...item, quantity: item.quantity + 1 } : item
        ));
    };

    const decrementQuantity = (id) => {
        setItems(items.map(item => {
            if (item.id === id && item.quantity > 1) {
                return { ...item, quantity: item.quantity - 1 };
            }
            return item;
        }));
    };

    return(
        <div className='UserPage'>
            <Header/>
            <h1>User Info</h1>
            <table className='Usertabel'>
                    <tr width='100%'></tr>
                    <td className='column1User' width='20%'>
                        <div className='Basics'>
                            <tr>
                                <td>username:</td>
                                <td>Nithya.P</td>
                            </tr>
                            <tr>
                                <td>Password:</td>
                                <td>******</td>
                            </tr>
                            <tr>
                                <td>email:</td>
                                <td>NithyaP@mail.com</td>
                            </tr>
                            <tr>
                                <td>Phone:</td>
                                <td>1234567890</td>
                            </tr>
                        </div>
                    </td>  
                    <td className='column2User' width='80%'>  
                        <div className='Address'>
                            <tr>
                                <td>Current Address: </td>
                                <td>123, 1st main, 4th block, jaynagar, Bangalore, India</td>
                            </tr>
                            <button>Change address</button>
                        </div>
                    </td>  
            </table>
            <hr classname="hr"/>
            <div className='PastHistory'>
                <h3>Past Orders</h3>
                <div className="cart-subtotal">
          <h2>CART SUBTOTAL</h2>
          {items.map(item => (
            <div key={item.id} className="subtotal-item">
              <img src={item.imageUrl} alt={item.name} className="subtotal-image" />
              <div className="subtotal-details">
                <p>{item.name}</p>
                <p>Rs.{item.price * item.quantity}</p>
              </div>
            </div>
          ))}
          <div className="total">SUBTOTAL: Rs.{subtotal}</div>
          <br/>
          <div className="checkout-button">
            <input className="checkout-button" type="button" value="Checkout" />
          </div>
        </div>
            </div>
            <Footer/>
        </div>
    );
};


export default User;
